import React from 'react';
import * as SVG from 'react-native-svg';
import * as DC from '../dc/runtime';

const DCLogic = DC.DCLogic;

/* ---------------------------------------------------------------- logic */
class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { stage: 'ask', a1: '', a2: '', wrong: false, tries: 0, p1: '', p2: '' };
  }
  renderVals() {
    const { stage, a1, a2, wrong, tries, p1, p2 } = this.state;
    const backend = !!this.props.backend;
    const busy = backend && !!this.props.busy;
    const askBlocked = !a1.trim() || !a2.trim() || busy;
    const full = /^\d{4}$/.test(p1) && /^\d{4}$/.test(p2);
    const pinDiff = full && p1 !== p2;
    const pinBlocked = !full || pinDiff || busy;
    const digits = (v) => v.replace(/[^0-9]/g, '').slice(0, 4);
    const q1Text = backend && this.props.q1Text ? this.props.q1Text : 'What was the name of your first pet?';
    const q2Text = backend && this.props.q2Text ? this.props.q2Text : 'What was the name of your first school?';
    const apiWrong = backend ? !!this.props.error : wrong;
    const wrongText = backend && this.props.error
      ? this.props.error
      : ('These answers do not match. ' + (3 - tries) + (tries === 2 ? ' try left.' : ' tries left.'));
    return {
      isAsk: stage === 'ask',
      isNew: stage === 'new',
      isDone: stage === 'done',
      isStuck: stage === 'stuck',
      q1Text, q2Text,
      wrongText,
      a1, a2, wrong: apiWrong, p1, p2, pinDiff, askBlocked, pinBlocked,
      askBg: askBlocked ? '#8C9A94' : '#0B6E4F',
      pinBg: pinBlocked ? '#8C9A94' : '#0B6E4F',
      setA1: (e) => { if (this.props.clearError) this.props.clearError(); this.setState({ a1: e.target.value, wrong: false }); },
      setA2: (e) => { if (this.props.clearError) this.props.clearError(); this.setState({ a2: e.target.value, wrong: false }); },
      setP1: (e) => this.setState({ p1: digits(e.target.value) }),
      setP2: (e) => this.setState({ p2: digits(e.target.value) }),
      check: async () => {
        if (backend && this.props.verifyAnswers) {
          const r = await this.props.verifyAnswers(a1, a2);
          if (r && r.ok) this.setState({ stage: 'new', tries: 0, wrong: false });
          else if (r && r.locked) this.setState({ stage: 'stuck', tries: 3, wrong: false });
          else this.setState({ tries: tries + 1, wrong: true });
          return;
        }
        if (!/wrong/i.test(a1 + a2)) this.setState({ stage: 'new', tries: 0 });
        else if (tries + 1 >= 3) this.setState({ stage: 'stuck', tries: 3, wrong: false });
        else this.setState({ tries: tries + 1, wrong: true });
      },
      save: async () => {
        if (backend && this.props.resetPin) {
          const r = await this.props.resetPin(p1);
          if (r && r.ok) this.setState({ stage: 'done' });
          return;
        }
        this.setState({ stage: 'done' });
      },
      reset: () => setTimeout(() => this.setState({ stage: 'ask', a1: '', a2: '', p1: '', p2: '', tries: 0, wrong: false }), 300)
    };
  }
}

